mongodb:createCollection.mongodb:options:
{
    validator: {
        $jsonSchema: {
            bsonType: "object",
            required: ["_id", "payment_status", "order_id", "created_at", "event_status", "attempt_count", "next_attempt_at"],
            properties: {
            _id: {
                bsonType: "objectId"
            }
            payment_status: {
                bsonType: "string"
            },
            created_at: {
                bsonType: "date"
            },
            event_status: {
                bsonType: "string"
            },
            attempt_count: {
                bsonType: "int"
            },
            next_attempt_at: {
                bsonType: "date"
            },
            order_id: {
                bsonType: "int",
            },
            sending_started_at: {
                bsonType: "date",
            }
        }
    }
},
validationAction: "error",
validationLevel: "strict"
}
